/* ---------- التحويل من الصيغة المضغوطة ---------- */
const LINKS = RAW.map(function (r, i) {
  const link = {
    id: i + 1,
    title: r[0],
    url: r[1],
    desc: r[2],
    cats: r[3].split(" "),
    lang: r[4],
    tier: r[5],
    votes: r[6] || 0,
    safe: !r[7]
  };
  if (r[7]) link.warn = r[7];
  return link;
}).filter(function (l) {
  return l.title && l.url && l.desc;
});